import assert from 'node:assert/strict';import Worker from '../dist/server/index.js';import {fixture} from './friend-server.mjs';const f=fixture({measure:true}),realNow=Date.now;let now=realNow();Date.now=()=>now;async function call(path,method='GET',body){const r=await Worker.fetch(new Request('https://ranking.test'+path,{method,headers:{'oai-authenticated-user-id':'cache','X-Kanji-Device':'1'.repeat(32),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}),f.env);const v=await r.json();assert.equal(r.status,200,JSON.stringify(v));return v;}const items=[{char:'一',level:10,equippedReadings:['イチ']},{char:'山',level:10,equippedReadings:['サン']},{char:'小',level:10,equippedReadings:['ショウ']}];try{await call('/api/profile','PUT',{name:'キャッシュ',char:'一',frame:'plain',color:'gold',glow:'none'});await call('/api/challenges/score','POST',{mode:'endless',wins:2,kills:6,items});assert.equal((await call('/api/leaderboard?rule=endless')).entries[0].wins,2);await call('/api/challenges/score','POST',{mode:'endless',wins:3,kills:9,items});assert.equal((await call('/api/leaderboard?rule=endless')).entries[0].wins,2);now+=30001;const results=await Promise.all(Array.from({length:200},()=>call('/api/leaderboard?rule=endless')));assert(results.every(r=>[2,3].includes(r.entries[0].wins)));assert.equal((await call('/api/leaderboard?rule=endless')).entries[0].wins,3);console.log('PASS 200 concurrent cache refresh reads; score persists, existing 30s cache delays visibility, latest score appears after expiry.');}finally{Date.now=realNow;f.sqlite.close();}
